text:
  background-image: var(--icon-more);
  background-position: center center;
  background-repeat: no-repeat;
  inline-size: var(--list-item-buttons-size);
  block-size: var(--list-item-buttons-size);
  display: none;

  :where(.bookRow-container, .listRow-container):hover &,
  #books:focus-visible :where(.bookRow, .listRow).selected > div & {
    display: unset;
  }
}

/* Cards pane */

#cardsPane {
  position: relative;
  grid-area: cards;
  display: flex;
  flex-direction: column;
  overflow-y: hidden;
  font-size: 1rem;
  background-color: var(--layout-background-1);
}

